//! Write Forge plugins in Rust.
//!
//! A plugin is a WebAssembly component for the `forge:editor/plugin` world
//! (`wit/forge-editor.wit`). The raw bindings, generated by `wit-bindgen`,
//! are in [`bindings`]; this crate adds the plumbing that makes the
//! callback-style API pleasant: commands and answers are closures.
//!
//! ```ignore
//! use forge_plugin_sdk::{command, forge_plugin, read_string, Buffer};
//!
//! fn init() -> Result<(), String> {
//!     command("greet", "Ask for a name and insert a greeting.", |_prefix| {
//!         read_string("Name: ", "", |name| {
//!             if let Some(name) = name {
//!                 Buffer::current().insert(&format!("Hello, {name}!"));
//!             }
//!         });
//!         Ok(())
//!     })
//! }
//!
//! forge_plugin!(init);
//! ```
//!
//! Forge calls a plugin and waits for it to return; a plugin never waits
//! for the user. So questions take a closure that runs when the answer
//! arrives, and `run_command` / prompts / messages take effect after the
//! current call returns.
//!
//! Build with `cargo build --release --target wasm32-wasip2` (install the
//! target once with `rustup target add wasm32-wasip2`).
//!
//! WASI 0.3: enable the `wasi` feature for the `wasip3` crate's APIs.
//!
//! Since API 0.1.2 / 0.1.3 there's more than commands and questions:
//! running programs ([`spawn`]), background commands
//! ([`command_background`]), reading one key ([`read_key`]), typing keys
//! ([`execute_keys`]), and completion: annotations for minibuffer lists
//! ([`annotate`]) and candidates at point ([`completion_source`]). The
//! crate targets the `plugin-full` world, so every plugin can use all of
//! it; a plugin only imports what it calls.

#![warn(missing_docs)]

use std::cell::RefCell;
use std::collections::HashMap;

/// Generated bindings for the `forge:editor/plugin` world.
#[allow(missing_docs)] // wit-bindgen does not emit doc comments for the generated items
pub mod bindings {
    wit_bindgen::generate!({
        path: "../../wit",
        world: "forge:editor/plugin-full",
        pub_export_macro: true,
        default_bindings_module: "forge_plugin_sdk::bindings",
    });
}

