type CommandFn = Box<dyn Fn(Option<i64>) -> Result<(), String>>;
type AnswerFn = Box<dyn FnOnce(Option<String>)>;
type EventFn = Box<dyn Fn(&Event)>;
type OutputFn = Box<dyn FnMut(&[u8])>;
type ExitFn = Box<dyn FnOnce(Option<i32>)>;
type ProcessFns = (Option<OutputFn>, Option<ExitFn>);
type AnnotateFn = Box<dyn Fn(&[String]) -> Vec<String>>;
type SourceFn = Box<dyn Fn(CompletionRequest)>;
type CommitFn = Box<dyn Fn(&str, &str)>;
type LocateFn = Box<dyn Fn(&Selection)>;
type ResponseFn = Box<dyn FnOnce(Result<HttpResponse, String>)>;

thread_local! {
    static COMMANDS: RefCell<HashMap<String, std::rc::Rc<CommandFn>>> = RefCell::new(HashMap::new());
    static ANSWERS: RefCell<HashMap<u32, AnswerFn>> = RefCell::new(HashMap::new());
    static EVENTS: RefCell<Vec<(EventKind, std::rc::Rc<EventFn>)>> = const { RefCell::new(Vec::new()) };
    static PROCESSES: RefCell<HashMap<u32, ProcessFns>> = RefCell::new(HashMap::new());
    static ANNOTATORS: RefCell<HashMap<String, std::rc::Rc<AnnotateFn>>> = RefCell::new(HashMap::new());
    static SOURCES: RefCell<HashMap<String, std::rc::Rc<SourceFn>>> = RefCell::new(HashMap::new());
    static COMMIT: RefCell<Option<CommitFn>> = const { RefCell::new(None) };
    static LOCATE: RefCell<Option<LocateFn>> = const { RefCell::new(None) };
    static RESPONSES: RefCell<HashMap<u32, ResponseFn>> = RefCell::new(HashMap::new());
}

fn kind_of(e: &Event) -> EventKind {
    match e {
        Event::BufferOpened(_) => EventKind::BufferOpened,
        Event::BufferKilled(_) => EventKind::BufferKilled,
        Event::BufferChanged(_) => EventKind::BufferChanged,
        Event::BufferSaved(_) => EventKind::BufferSaved,
        Event::ModeChanged(_) => EventKind::ModeChanged,
    }
}

/// Register a command. `run` gets the prefix argument (C-u / M-5), if any.
pub fn command(
    name: &str,
    doc: &str,
    run: impl Fn(Option<i64>) -> Result<(), String> + 'static,
) -> Result<(), String> {
    commands::register(name, doc)?;
    COMMANDS.with(|c| {
        c.borrow_mut()
            .insert(name.to_string(), std::rc::Rc::new(Box::new(run)))
    });
    Ok(())
}

/// Register a command that runs in the background, on a snapshot of the
/// editor, without blocking it (see `commands.register-background`).
pub fn command_background(
    name: &str,
    doc: &str,
    run: impl Fn(Option<i64>) -> Result<(), String> + 'static,
) -> Result<(), String> {
    commands::register_background(name, doc)?;
    COMMANDS.with(|c| {
        c.borrow_mut()
            .insert(name.to_string(), std::rc::Rc::new(Box::new(run)))
    });
    Ok(())
}

/// Run a command (built-in or a plugin's) after this call returns.
pub fn run_command(name: &str) -> Result<(), String> {
    commands::run(name)
}

/// Is `name` a command (a built-in or a plugin's)?
pub fn command_exists(name: &str) -> bool {
    commands::exists(name)
}

/// Run `run` each time the editor has been idle for `seconds` after input
///: registers it as the command `name`. Needs Forge
/// 0.1.10.
pub fn when_idle(
    name: &str,
    doc: &str,
    seconds: f64,
    run: impl Fn() + 'static,
) -> Result<(), String> {
    command(name, doc, move |_| {
        run();
        Ok(())
    })?;
    commands::run_when_idle(name, seconds)
}

/// Read one key; `then` gets its description ("a", "C-x", "RET"), None
/// for C-g.
pub fn read_key(prompt: &str, then: impl FnOnce(Option<String>) + 'static) {
    let id = minibuffer::read_key(prompt);
    ANSWERS.with(|a| a.borrow_mut().insert(id, Box::new(then)));
}

/// Handle keys ("C-x C-f") as if typed, after this call returns.
pub fn execute_keys(keys: &str) -> Result<(), String> {
    keymap::execute_keys(keys)
}

/// Put a transient map on top of every other layer until it is popped.
/// `one_shot` ends it after the first key it resolves; `timeout` (seconds)
/// ends it after a while; `on_unbound` says what a key the map doesn't bind
/// does (`stay`, `swallow`, `exit` -- take the map down and let the key
/// resolve again in what's left).
#[derive(Debug, Clone, Default)]
pub struct TransientOpts {
    /// Whether the transient resolves and disappears after one command.
    pub one_shot: bool,
    /// "stay", "swallow" or "exit"; None means "exit".
    pub on_unbound: Option<&'static str>,
    /// Seconds; None or 0 means it stays until popped.
    pub timeout: Option<f64>,
}

impl TransientOpts {
    /// Resolve and close after one command.
    pub fn one_shot(mut self, yes: bool) -> Self {
        self.one_shot = yes;
        self
    }

    /// What to do on an unbound key: `"stay"`, `"swallow"` or `"exit"`.
    pub fn on_unbound(mut self, policy: &'static str) -> Self {
        self.on_unbound = Some(policy);
        self
    }

    /// Close automatically after `seconds` (0 or None: never).
    pub fn timeout(mut self, seconds: f64) -> Self {
        self.timeout = Some(seconds);
        self
    }
}

/// Install a transient map on top of every other layer. Bind into it with
/// [`keymap::bind_transient`] first; while it is up, `where-is`,
/// `describe-key`, prefix hints and the menu shortcuts all see it.
pub fn push_transient(name: &str, opts: TransientOpts) -> Result<(), String> {
    use bindings::forge::editor::keymap::{OnUnbound, TransientOpts as Opts};
    let on_unbound = match opts.on_unbound {
        Some("stay") => Some(OnUnbound::Stay),
        Some("swallow") => Some(OnUnbound::Swallow),
        _ => None,
    };
    let mut list = Vec::new();
    if opts.one_shot {
        list.push(Opts::OneShot);
    }
    if let Some(p) = on_unbound {
        list.push(Opts::OnUnbound(p));
    }
    if let Some(secs) = opts.timeout.filter(|s| *s > 0.0) {
        list.push(Opts::Timeout(secs));
    }
    keymap::push_transient(name, &list)
}

/// Take a transient map down. Err if it wasn't up.
pub fn pop_transient(name: &str) -> Result<(), String> {
    keymap::pop_transient(name)
}

/// The transient maps that are up, outermost first.
pub fn live_transients() -> Vec<String> {
    keymap::transients()
}

/// Bind `keys` to `command` in the transient map `name`.
pub fn bind_transient(name: &str, keys: &str, command: &str) -> Result<(), String> {
    keymap::bind_transient(name, keys, command)
}

/// Bind `keys` to `command` in the conditional layer `name`, and set the
/// condition it applies while.
///
/// `when` is the notation `forge_core::keymap::Condition` prints:
/// `region-active`, `read-only`, `in-comment`, `in-string`, `in-git-repo`,
/// `major-derives-from(MODE)`, `minor-mode-on(MODE)`, and the combinators
/// `not(CONDITION)`, `all(CONDITION ...)` and `any(CONDITION ...)`.
///
/// A layer sits above the modes and below the buffer-local map, so it is
/// where a plugin's keys belong without taking the user's own away. Calling
/// this again for the same layer replaces the condition and keeps the
/// bindings, and a layer with no condition is never up.
pub fn bind_in_layer(name: &str, when: &str, keys: &str, command: &str) -> Result<(), String> {
    keymap::bind_layer(name, when, keys, command)
}

/// Drop the conditional layer `name` and its bindings. Err if there was none.
pub fn remove_layer(name: &str) -> Result<bool, String> {
    keymap::remove_layer(name)
}

/// Bind `keys` to `command` in the prompt map `name`, which is named by
/// what is asking: "find-file", "dired", "m-x", "completion-popup".
///
/// A prompt with no map of its own uses the default one, so a binding here
/// only shadows the key it names. Anything the map doesn't bind is typed,
/// which is what lets a plugin add a key of its own without taking the
/// editing keys away.
pub fn bind_in_prompt(name: &str, keys: &str, command: &str) -> Result<(), String> {
    keymap::bind_prompt(name, keys, command)
}

/// Bind `keys` to `command` in the region map `name`, the keymap a
/// stretch of text brings with it: it applies while point is inside a
/// decoration that names it (see `decorations::set_regions`).
///
/// `<mouse-1>` and `<mouse-2>` are keys this takes, so a clickable name, a
/// magit section or a column header gets its behaviour this way rather
/// than by reading the mouse itself. A region map sits above the
/// buffer-local map and below the conditional layers.
pub fn bind_in_region(name: &str, keys: &str, command: &str) -> Result<(), String> {
    keymap::bind_region(name, keys, command)
}

/// Drop the region map `name` and its bindings. Err if there was none.
pub fn remove_region(name: &str) -> Result<bool, String> {
    keymap::remove_region(name)
}

/// Bind `keys` to `command` for every file under `root`, the way a
/// project's `.dir-locals.el` bindings work. The innermost project wins,
/// so a repository inside a directory that has bindings of its own uses
/// its own.
///
/// A project map sits above the major mode and below the minor modes, so
/// a checkout can add keys without taking the user's away.
pub fn bind_in_project(root: &str, keys: &str, command: &str) -> Result<(), String> {
    keymap::bind_project(root, keys, command)
}

/// Drop the project map for `root`. Err if there was none.
pub fn remove_project(root: &str) -> Result<bool, String> {
    keymap::remove_project(root)
}

/// Bind `keys` to `command` in `mode`'s keymap.
pub fn bind_in_mode(mode: &str, keys: &str, command: &str) -> Result<(), String> {
    keymap::bind(&Scope::Mode(mode.to_string()), keys, command)
}

// ---------------------------------------------------------- processes

/// A program this plugin started (see [`spawn`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Process(
    /// The host's handle for the process.
    pub u32,
);

impl Process {
    /// Write `data` to the process's standard input.
    pub fn write(&self, data: &[u8]) -> Result<(), String> {
        processes::write(self.0, data)
    }

    /// Close standard input (the process sees end of file).
    pub fn close_input(&self) {
        processes::close_input(self.0)
    }

    /// Kill the process.
    pub fn kill(&self) {
        processes::kill(self.0)
    }
}

/// Start `program` with `args` in `dir` (default: the current buffer's
/// project). Needs the `processes` permission naming it. Output arrives in
/// `on_output` (stdout, in order), then `on_exit` with the exit code.
pub fn spawn(
    program: &str,
    args: &[String],
    dir: Option<&str>,
    on_output: impl FnMut(&[u8]) + 'static,
    on_exit: impl FnOnce(Option<i32>) + 'static,
) -> Result<Process, String> {
    let id = processes::spawn(program, args, dir)?;
    PROCESSES.with(|p| {
        p.borrow_mut()
            .insert(id, (Some(Box::new(on_output)), Some(Box::new(on_exit))))
    });
    Ok(Process(id))
}

/// Like [`spawn`], with `env` set for the program, and `on_exit` also
/// getting what it wrote to stderr (the first 64 KiB, lossily decoded):
/// the reason a failed command gives. Needs Forge 0.1.9.
pub fn spawn_with(
    program: &str,
    args: &[String],
    dir: Option<&str>,
    env: &[(&str, &str)],
    on_output: impl FnMut(&[u8]) + 'static,
    on_exit: impl FnOnce(Option<i32>, String) + 'static,
) -> Result<Process, String> {
    let env: Vec<(String, String)> = env
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect();
    let id = processes::spawn_with(program, args, dir, &env)?;
    let exit = move |code: Option<i32>| {
        let err = processes::error_output(id);
        on_exit(code, String::from_utf8_lossy(&err).into_owned());
    };
    PROCESSES.with(|p| {
        p.borrow_mut()
            .insert(id, (Some(Box::new(on_output)), Some(Box::new(exit))))
    });
    Ok(Process(id))
}

/// The project a file is in, if any.
pub fn project_root(path: &str) -> Option<String> {
    processes::project_root(path)
}

// ---------------------------------------------------------------- http
//
// Web requests are asynchronous ([`get_async`] / [`request_async`]): they
// return at once and deliver the answer during idle time, so the network
// never holds up the editor. There is no synchronous form: waiting on the
// network blocks everything, and a plugin that must wait should split its
// work across the callback instead.

/// A GET of `url` that returns at once with an id; `on_response` runs when
/// the answer arrives (the response, or the reason it failed), during idle
/// time. This is the form to use in general: it never blocks the editor.
/// Needs the `http` permission. See [`cancel`].
pub fn get_async(
    url: &str,
    headers: &[(&str, &str)],
    on_response: impl FnOnce(Result<HttpResponse, String>) + 'static,
) -> Result<u32, String> {
    let headers = owned_headers(headers);
    let id = http::get_async(url, &headers)?;
    RESPONSES.with(|r| r.borrow_mut().insert(id, Box::new(on_response)));
    Ok(id)
}

/// Like [`get_async`], for another HTTP `method`, with an optional `body`.
pub fn request_async(
    method: &str,
    url: &str,
    headers: &[(&str, &str)],
    body: Option<&[u8]>,
    on_response: impl FnOnce(Result<HttpResponse, String>) + 'static,
) -> Result<u32, String> {
    let headers = owned_headers(headers);
    let id = http::http_request_async(method, url, &headers, body)?;
    RESPONSES.with(|r| r.borrow_mut().insert(id, Box::new(on_response)));
    Ok(id)
}

/// Give up on an asynchronous request started with [`get_async`] /
/// [`request_async`]: its `on_response` never runs.
pub fn cancel(request: u32) {
    RESPONSES.with(|r| r.borrow_mut().remove(&request));
    http::cancel(request);
}

fn owned_headers(headers: &[(&str, &str)]) -> Vec<(String, String)> {
    headers
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect()
}

// ------------------------------------------------------------ menus

/// One entry in a menu: a label and the command it runs, or a separator
/// (an empty command).
pub fn menu_item(label: &str, command: &str) -> MenuItem {
    MenuItem {
        label: label.to_string(),
        command: command.to_string(),
    }
}

/// A separator: a rule between groups of items in a menu.
pub fn menu_separator() -> MenuItem {
    menu_item("", "")
}

/// Add a menu to the bar, after the built-in ones. Fails if this plugin
/// already has one, or if the title is taken.
pub fn define_menu(title: &str, items: &[MenuItem]) -> Result<(), String> {
    menus::define(title, items)
}

/// Add a menu that only shows while `mode` is the buffer's major mode or
/// one it derives from, the way a mode's own menu does.
pub fn define_menu_for_mode(title: &str, items: &[MenuItem], mode: &str) -> Result<(), String> {
    menus::define_for_mode(title, items, mode)
}

/// Add items to a menu someone else defined — a built-in one, or another
/// plugin's — after the ones already there.
pub fn extend_menu(title: &str, items: &[MenuItem]) -> Result<(), String> {
    menus::extend(title, items)
}

/// Add items to the submenu called `label` in the menu called `title`,
/// after the ones already there. A missing label becomes a submenu
/// header; a label on a plain item fails, since opening it would hide
/// the command it runs.
pub fn extend_submenu(menu: &str, label: &str, items: &[MenuItem]) -> Result<(), String> {
    menus::extend_submenu(menu, label, items)
}

/// Take back what this plugin added to `title`.
pub fn remove_menu(title: &str) -> Result<(), String> {
    menus::remove(title)
}

/// Turn the menu bar on or off in this buffer.
pub fn set_menu_bar(enabled: bool) {
    menus::set_enabled(enabled);
}

/// Whether the menu bar is on in this buffer.
pub fn menu_bar_enabled() -> bool {
    menus::enabled()
}

/// Open a menu by title, or close the open one when `title` is empty.
pub fn open_menu(title: &str) {
    menus::open(title);
}

/// Close whatever menu is open.
pub fn close_menu() {
    menus::close();
}

/// The open menu's title, or none.
pub fn open_menu_title() -> Option<String> {
    menus::open_title()
}

/// Run the item under the cursor in the open menu.
pub fn choose_menu_item() -> bool {
    menus::choose()
}

/// The item under the cursor, for showing what it does.
pub fn menu_selection() -> Option<MenuSelection> {
    menus::selection()
}

// --------------------------------------------------------- completion

/// A request for candidates at point (see [`completion_source`]).
#[derive(Debug, Clone, Copy)]
pub struct CompletionRequest {
    /// The session id to answer with.
    pub id: u32,
    /// The buffer the request came from.
    pub buffer: u32,
    /// The point the request came from.
    pub point: Position,
}

impl CompletionRequest {
    /// Answer it: `span` is the text to replace. Now or later.
    pub fn deliver(&self, span: Span, candidates: &[Candidate]) {
        completion::deliver(self.id, span, candidates)
    }

    /// Answer it with decorated candidates: each may show a margin (an
    /// icon or kind) before it and say it is deprecated. Now or later.
    pub fn deliver_decorated(&self, span: Span, candidates: &[DecoratedCandidate]) {
        completion::deliver_decorated(self.id, span, candidates)
    }

    /// Answer with detailed candidates (decoration plus documentation and
    /// a source location). Supersedes `deliver_decorated`.
    pub fn deliver_detailed(&self, span: Span, candidates: &[DetailedCandidate]) {
        completion::deliver_detailed(self.id, span, candidates)
    }
}

/// A completion candidate with an optional annotation.
pub fn candidate(text: impl Into<String>, annotation: Option<&str>) -> Candidate {
    Candidate {
        text: text.into(),
        annotation: annotation.map(String::from),
    }
}

/// A completion candidate with a display margin (an icon or kind, shown
/// before it) and a deprecation flag.
pub fn decorated_candidate(
    text: impl Into<String>,
    annotation: Option<&str>,
    margin: Option<&str>,
    deprecated: bool,
) -> DecoratedCandidate {
    DecoratedCandidate {
        text: text.into(),
        annotation: annotation.map(String::from),
        margin: margin.map(String::from),
        deprecated,
    }
}

/// A completion candidate with decoration, documentation and a location.
pub fn detailed_candidate(
    text: impl Into<String>,
    annotation: Option<&str>,
    margin: Option<&str>,
    deprecated: bool,
    documentation: Option<&str>,
    location: Option<Location>,
) -> DetailedCandidate {
    DetailedCandidate {
        text: text.into(),
        annotation: annotation.map(String::from),
        margin: margin.map(String::from),
        deprecated,
        documentation: documentation.map(String::from),
        location,
    }
}

/// Annotate the candidates of a minibuffer `category` ("command",
/// "buffer", ...): `f` gets the list once, returns one note per candidate.
pub fn annotate(category: &str, f: impl Fn(&[String]) -> Vec<String> + 'static) {
    ANNOTATORS.with(|a| {
        a.borrow_mut()
            .insert(category.to_string(), std::rc::Rc::new(Box::new(f)))
    });
    completion::annotate_category(category);
}

/// Run `command` (one this plugin defined with [`command`]) whenever the
/// selection in an open list changes, so it can preview candidates as the
/// cursor moves over them (consult's live preview). Needs Forge 0.1.20.
/// The command runs like any other: it can call [`selected`] to see the
/// new selection, and should only move point or show a buffer.
pub fn on_selection_changed(command: &str) {
    completion::on_selection_changed(command);
}

/// How matching candidates are ordered: "length" (shortest first, then
/// alphabetical), "alpha", "history" (most recently used first, then
/// length), "history-length", or "position" (the order the source gave).
/// Only the first name that applies is used; unknown ones are ignored, so
/// a plugin asking for more than this Forge knows still loads.
pub fn set_sorting(styles: &[&str]) {
    let styles: Vec<String> = styles.iter().map(|s| s.to_string()).collect();
    completion::set_sorting(&styles);
}

/// The candidate under the cursor in the minibuffer's vertical list or a
/// popup at point, with where it is in the list. None when no list is
/// open.
pub fn selected() -> Option<Selection> {
    completion::selected()
}

/// Ask the source of the selected candidate where it is defined (corfu's
/// M-g). The source answers later, on its own: this only says whether a
/// source was asked (false when no list is open).
pub fn locate() -> bool {
    completion::locate()
}

/// Widen the popup at point to fit its candidates, between `min_width`
/// and `max_width` columns (0 leaves that end to Forge). A terminal has
/// no borders, so `border` is ignored.
pub fn set_popup_frame(min_width: u32, max_width: u32, border: u32) {
    completion::set_popup_frame(min_width, max_width, border);
}

// ---- the auxiliary popup beside the completion popup (corfu-popupinfo).
// Needs Forge 0.1.18.

/// Ask for an auxiliary popup beside the completion popup showing the
/// selection's documentation and/or location (corfu-popupinfo).
/// `delay_ms` waits after the selection settles before showing (0: at
/// once); `max_width` and `max_height` cap it (0: Forge's default).
pub fn set_popup_info(
    show_documentation: bool,
    show_location: bool,
    delay_ms: u32,
    max_width: u32,
    max_height: u32,
) {
    completion::set_popup_info(
        show_documentation,
        show_location,
        delay_ms,
        max_width,
        max_height,
    );
}

/// Turn the auxiliary popup off, or back on (corfu-popupinfo-toggle).
pub fn toggle_popup_info() {
    completion::toggle_popup_info();
}

/// Scroll the auxiliary popup a page down (or up)
/// (corfu-popupinfo-scroll-down / -scroll-up).
pub fn scroll_popup_info(down: bool) {
    completion::scroll_popup_info(down);
}

/// Scroll the auxiliary popup to its first line (corfu-popupinfo-beginning).
pub fn popup_info_beginning() {
    completion::popup_info_beginning();
}

/// Scroll the auxiliary popup to its last line (corfu-popupinfo-end).
pub fn popup_info_end() {
    completion::popup_info_end();
}

// ---- driving the popup (a completion plugin like corfu). Needs Forge
// 0.1.14. Each of `next`..`insert_separator` queues a request the editor
// carries out after this call returns, the way `run_command` does.

/// The popup's session at point, if a completion popup is open.
pub fn current() -> Option<Session> {
    completion::current()
}

/// Set the popup's policy: how many rows, which keys select and take
/// candidates, when it quits. Replaces the whole set.
pub fn set_options(options: &Options) {
    completion::set_options(options);
}

/// Move the selection `n` candidates forward (negative: back).
pub fn next(n: i32) {
    completion::next(n);
}

/// Move the selection `n` candidates back.
pub fn previous(n: i32) {
    completion::previous(n);
}

/// Select the first candidate.
pub fn first() {
    completion::first();
}

/// Select the last candidate.
pub fn last() {
    completion::last();
}

/// Move a page down (or up) the list.
pub fn scroll(down: bool) {
    completion::scroll(down);
}

/// Take the selected candidate and finish.
pub fn accept() {
    completion::accept();
}

/// Grow the typed text to what every candidate shares.
pub fn expand() {
    completion::expand();
}

/// Close the popup, keeping what was typed.
pub fn quit() {
    completion::quit();
}

/// Deselect the candidate; again, quit.
pub fn reset() {
    completion::reset();
}

/// Take the candidate on popup row `row` (the row a number labels).
pub fn accept_row(row: u32) {
    completion::accept_row(row);
}

/// Wait for the next key to name a candidate: "insert", "complete" or
/// "jump".
pub fn arm_quick(action: &str) {
    completion::arm_quick(action);
}

/// Insert the component separator and keep completing.
pub fn insert_separator() {
    completion::insert_separator();
}

/// Provide candidates at point in buffers of `modes` (and modes derived
/// from them; empty: every buffer).
pub fn completion_source(
    name: &str,
    modes: &[String],
    f: impl Fn(CompletionRequest) + 'static,
) -> Result<(), String> {
    completion::register_source(name, modes)?;
    SOURCES.with(|s| {
        s.borrow_mut()
            .insert(name.to_string(), std::rc::Rc::new(Box::new(f)))
    });
    Ok(())
}

/// Run `f` when a candidate is committed (inserted): `candidate` is its
/// text and `status` is "finished", "exact", "sole" or "continued"
/// (corfu's `:exit-function`).
pub fn on_commit(f: impl Fn(&str, &str) + 'static) {
    COMMIT.with(|c| *c.borrow_mut() = Some(Box::new(f)));
}

/// Run `f` when Forge asks where the selected candidate is defined
/// (corfu's M-g, via [`locate`]): `f` gets the selection and reports the
/// place itself when it knows it, usually with [`message`].
pub fn on_resolve_location(f: impl Fn(&Selection) + 'static) {
    LOCATE.with(|c| *c.borrow_mut() = Some(Box::new(f)));
}

/// Ask for a line of text; `then` gets it (None if the user pressed C-g).
pub fn read_string(prompt: &str, initial: &str, then: impl FnOnce(Option<String>) + 'static) {
    let id = minibuffer::read_string(prompt, initial);
    ANSWERS.with(|a| a.borrow_mut().insert(id, Box::new(then)));
}

/// Ask with TAB completion over `candidates`.
pub fn completing_read(
    prompt: &str,
    candidates: &[String],
    require_match: bool,
    then: impl FnOnce(Option<String>) + 'static,
) {
    let id = minibuffer::completing_read(prompt, candidates, require_match);
    ANSWERS.with(|a| a.borrow_mut().insert(id, Box::new(then)));
}

/// Like [`completing_read`], but takes over the prompt that is open (the
/// answer replaces its input, C-g leaves it as it was). Needs Forge 0.1.24;
/// with no prompt open it acts like [`completing_read`].
pub fn completing_read_over(
    prompt: &str,
    candidates: &[String],
    require_match: bool,
    then: impl FnOnce(Option<String>) + 'static,
) {
    let id = minibuffer::completing_read_over(prompt, candidates, require_match);
    ANSWERS.with(|a| a.borrow_mut().insert(id, Box::new(then)));
}

/// Ask a y-or-n question; `then` gets true for y (false for n or C-g).
pub fn y_or_n(prompt: &str, then: impl FnOnce(bool) + 'static) {
    let id = minibuffer::y_or_n(prompt);
    ANSWERS.with(|a| {
        a.borrow_mut().insert(
            id,
            Box::new(move |ans: Option<String>| then(ans.as_deref() == Some("y"))),
        )
    });
}

/// Run `f` for every event of `kind` (subscribing to it).
pub fn on(kind: EventKind, f: impl Fn(&Event) + 'static) {
    bindings::forge::editor::events::subscribe(kind);
    EVENTS.with(|e| e.borrow_mut().push((kind, std::rc::Rc::new(Box::new(f)))));
}

/// Like [`on`], but the handlers of `kind` run in the background.
pub fn on_background(kind: EventKind, f: impl Fn(&Event) + 'static) {
    bindings::forge::editor::events::subscribe_background(kind);
    EVENTS.with(|e| e.borrow_mut().push((kind, std::rc::Rc::new(Box::new(f)))));
}

/// The buffer an event is about.
pub fn event_buffer(e: &Event) -> u32 {
    match e {
        Event::BufferOpened(id)
        | Event::BufferKilled(id)
        | Event::BufferChanged(id)
        | Event::BufferSaved(id)
        | Event::ModeChanged(id) => *id,
    }
}

/// The settings the user gave this plugin in init.rhai with
/// `forge.plugin.config(name, #{ ... })`, as a JSON object (`{}` if none).
/// Read it in `init`; a change in init.rhai applies the next time the plugin
/// loads. Refuse a key you don't know (return an error from `init`, naming
/// it) so a typo isn't silent.
pub fn config_json() -> String {
    #[cfg(target_arch = "wasm32")]
    return bindings::forge::editor::config::get();
    #[cfg(not(target_arch = "wasm32"))]
    "{}".to_string()
}

/// Show a message in the echo area.
pub fn message(text: &str) {
    minibuffer::message(text);
}

/// Send a message to Forge's log (*Messages*) at the given level.
pub fn log_at(level: Level, msg: &str) {
    #[cfg(target_arch = "wasm32")]
    bindings::forge::editor::log::log(level, msg);
    // Lets plugin logic be unit-tested natively.
    #[cfg(not(target_arch = "wasm32"))]
    println!("[plugin {level:?}] {msg}");
}

/// Log a message at info level (see [`log_at`]).
pub fn log(msg: &str) {
    log_at(Level::Info, msg);
}

/// Log a message at debug level.
pub fn debug(msg: &str) {
    log_at(Level::Debug, msg);
}

/// Log a message at warning level.
pub fn warn(msg: &str) {
    log_at(Level::Warn, msg);
}

/// Log a message at error level.
pub fn error(msg: &str) {
    log_at(Level::Error, msg);
}

/// `format!`-style logging at info level.
#[macro_export]
macro_rules! plugin_log {
    ($($arg:tt)*) => {
        $crate::log(&::std::format!($($arg)*))
    };
}

/// The handler side, used by the export macros: dispatch to the closures
/// registered with [`command`], [`read_string`] and [`on`].
#[doc(hidden)]
pub mod dispatch {
    use super::*;

    pub fn run_command(name: String, prefix: Option<i64>) -> Result<(), String> {
        let f = COMMANDS.with(|c| c.borrow().get(&name).cloned());
        match f {
            Some(f) => f(prefix),
            None => Err(format!("this plugin has no command {name}")),
        }
    }

    pub fn on_event(event: Event) {
        let kind = kind_of(&event);
        let handlers: Vec<_> = EVENTS.with(|e| {
            e.borrow()
                .iter()
                .filter(|(k, _)| *k == kind)
                .map(|(_, f)| f.clone())
                .collect()
        });
        for f in handlers {
            f(&event);
        }
    }

    pub fn on_answer(request: u32, answer: Option<String>) {
        if let Some(f) = ANSWERS.with(|a| a.borrow_mut().remove(&request)) {
            f(answer);
        }
    }

    pub fn on_output(process: u32, data: Vec<u8>) {
        // Taken out while it runs, so it can spawn or write freely.
        let f = PROCESSES.with(|p| p.borrow_mut().get_mut(&process).and_then(|h| h.0.take()));
        if let Some(mut f) = f {
            f(&data);
            PROCESSES.with(|p| {
                if let Some(h) = p.borrow_mut().get_mut(&process) {
                    h.0 = Some(f);
                }
            });
        }
    }

    pub fn on_exit(process: u32, code: Option<i32>) {
        let exit = PROCESSES
            .with(|p| p.borrow_mut().remove(&process))
            .and_then(|h| h.1);
        if let Some(f) = exit {
            f(code);
        }
    }

    pub fn annotate(category: String, candidates: Vec<String>) -> Vec<String> {
        let f = ANNOTATORS.with(|a| a.borrow().get(&category).cloned());
        let mut out = f.map(|f| f(&candidates)).unwrap_or_default();
        out.resize(candidates.len(), String::new());
        out
    }

    pub fn complete(request: u32, source: String, buffer: u32, point: Position) {
        if let Some(f) = SOURCES.with(|s| s.borrow().get(&source).cloned()) {
            f(CompletionRequest {
                id: request,
                buffer,
                point,
            });
        }
    }

    pub fn commit(candidate: String, status: String) {
        let f = COMMIT.with(|c| c.borrow_mut().take());
        if let Some(f) = f {
            f(&candidate, &status);
            COMMIT.with(|c| *c.borrow_mut() = Some(f));
        }
    }

    pub fn resolve_location(selection: Selection) {
        let f = LOCATE.with(|c| c.borrow_mut().take());
        if let Some(f) = f {
            f(&selection);
            LOCATE.with(|c| *c.borrow_mut() = Some(f));
        }
    }

    pub fn on_response(request: u32, answer: Result<HttpResponse, String>) {
        let f = RESPONSES.with(|r| r.borrow_mut().remove(&request));
        if let Some(f) = f {
            f(answer);
        }
    }
}

#[cfg(any(target_arch = "wasm32", feature = "check-exports"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __export {
    ($t:ident) => {
        $crate::bindings::export!($t);
    };
}

#[cfg(not(any(target_arch = "wasm32", feature = "check-exports")))]
#[doc(hidden)]
#[macro_export]
macro_rules! __export {
    ($t:ident) => {};
}

/// Make `init` (a `fn() -> Result<(), String>`) the plugin's entry point.
/// Commands, questions and events are routed to the closures registered
/// with [`command`], [`read_string`] and [`on`].
#[macro_export]
macro_rules! forge_plugin {
    ($init:path) => {
        struct __ForgePlugin;

        impl $crate::bindings::Guest for __ForgePlugin {
            fn init() -> ::std::result::Result<(), ::std::string::String> {
                $init()
            }
        }

        impl $crate::bindings::exports::forge::editor::handler::Guest for __ForgePlugin {
            fn run_command(
                name: ::std::string::String,
                prefix_arg: ::std::option::Option<i64>,
            ) -> ::std::result::Result<(), ::std::string::String> {
                $crate::dispatch::run_command(name, prefix_arg)
            }
            fn on_event(event: $crate::Event) {
                $crate::dispatch::on_event(event)
            }
            fn on_answer(request: u32, answer: ::std::option::Option<::std::string::String>) {
                $crate::dispatch::on_answer(request, answer)
            }
        }

        impl $crate::bindings::exports::forge::editor::process_handler::Guest for __ForgePlugin {
            fn on_output(process: u32, data: ::std::vec::Vec<u8>) {
                $crate::dispatch::on_output(process, data)
            }
            fn on_exit(process: u32, code: ::std::option::Option<i32>) {
                $crate::dispatch::on_exit(process, code)
            }
        }

        impl $crate::bindings::exports::forge::editor::completion_handler::Guest for __ForgePlugin {
            fn annotate(
                category: ::std::string::String,
                candidates: ::std::vec::Vec<::std::string::String>,
            ) -> ::std::vec::Vec<::std::string::String> {
                $crate::dispatch::annotate(category, candidates)
            }
            fn complete(
                request: u32,
                source: ::std::string::String,
                buffer: u32,
                point: $crate::Position,
            ) {
                $crate::dispatch::complete(request, source, buffer, point)
            }
            fn commit(candidate: ::std::string::String, status: ::std::string::String) {
                $crate::dispatch::commit(candidate, status)
            }
            fn resolve_location(selection: $crate::Selection) {
                $crate::dispatch::resolve_location(selection)
            }
        }

        impl $crate::bindings::exports::forge::editor::http_handler::Guest for __ForgePlugin {
            fn on_response(
                request: $crate::HttpRequest,
                answer: ::std::result::Result<$crate::HttpResponse, ::std::string::String>,
            ) {
                $crate::dispatch::on_response(request, answer)
            }
        }

        // Only in the .wasm (or with the check-exports feature, for
        // `cargo check`): a native build, for `cargo test` of a plugin's
        // own logic, can't export names like these.
        $crate::__export!(__ForgePlugin);
        #[allow(dead_code)]
        const _: fn() -> ::std::result::Result<(), ::std::string::String> = $init;

        // The manifest, from Cargo.toml's [package.metadata.forge].
        $crate::manifest!();
    };
}
